const KEY='moonveil-universe-play-v1';const REV='moonveil-cloud-revision';const TOKEN='moonveil-cloud-player-token';const api='/api/save?slot=main';const el=document.createElement('aside');el.id='moonveil-cloud-controls';Object.assign(el.style,{position:'fixed',right:'12px',bottom:'12px',background:'#101b2c',color:'#fff',border:'1px solid #ad915a',padding:'8px',borderRadius:'12px',zIndex:'9999',font:'13px system-ui',maxWidth:'245px'});el.innerHTML='<details><summary>☁ Cloud save</summary><label>Player token <input id="moonveil-cloud-token" type="password" autocomplete="off" placeholder="From your private server" style="width:100%"></label><button id="moonveil-cloud-upload">Upload save</button><button id="moonveil-cloud-download">Download save</button><p id="moonveil-cloud-status" role="status" aria-live="polite"></p></details>';document.body.append(el);const input=el.querySelector('#moonveil-cloud-token');input.value=sessionStorage.getItem(TOKEN)||'';input.addEventListener('change',()=>sessionStorage.setItem(TOKEN,input.value));const status=s=>el.querySelector('#moonveil-cloud-status').textContent=s;async function call(method,payload){const headers={Authorization:'Bearer '+input.value};if(method==='PUT'){headers['Content-Type']='application/json';headers['If-Match']=sessionStorage.getItem(REV)||'0';}const r=await fetch(api,{method,headers,body:payload?JSON.stringify(payload):undefined});const data=await r.json();if(!r.ok)throw Error((data.error||r.statusText)+(r.status===409?' (reload cloud version first)':''));sessionStorage.setItem(REV,String(data.revision));return data;}el.querySelector('#moonveil-cloud-upload').addEventListener('click',async()=>{try{const raw=localStorage.getItem(KEY);if(!raw)throw Error('No local game to upload');await call('PUT',{game:JSON.parse(raw)});status('Uploaded successfully');}catch(e){status(e.message)}});el.querySelector('#moonveil-cloud-download').addEventListener('click',async()=>{try{const result=await call('GET');if(!confirm('Back up the local save, then replace it with the cloud save?'))return;const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(KEY+'-backup-'+Date.now(),previous);localStorage.setItem(KEY,JSON.stringify(result.game));status('Cloud save downloaded; reloading.');location.reload();}catch(e){status(e.message)}});